from datetime import datetime
from fastapi.testclient import TestClient

from src.main import app

client = TestClient(app)


def test_health_endpoint():
    """Test the /health endpoint returns correct status and timestamp format."""
    response = client.get("/health")

    assert response.status_code == 200
    data = response.json()

    assert data["status"] == "healthy"
    assert "timestamp" in data

    # Verify timestamp is in ISO format with Z suffix
    timestamp = data["timestamp"]
    assert timestamp.endswith("Z")

    # Verify timestamp can be parsed as ISO format
    parsed_timestamp = datetime.fromisoformat(timestamp.rstrip("Z"))
    assert isinstance(parsed_timestamp, datetime)
